export const meta = {
  name: 'b1-rigidification-map',
  description: 'Map the exact in-tree API needed to build the RigidifiedPic rigidification brick (section from HasRationalPoint, automorphism-unit bridge, trivialization/twist API, ring-level lm:aut wiring)',
  phases: [{ title: 'Map', detail: 'four parallel read-only API mappers over the Picard substrate' }],
}

phase('Map')

const ROOT = 'MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard'

const FINDING_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    summary: { type: 'string', description: 'One-paragraph verdict: is the needed API present? What is the shortest path?' },
    decls: {
      type: 'array',
      description: 'Relevant existing declarations found, with exact names, file:line, and signature sketch',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          name: { type: 'string' },
          location: { type: 'string', description: 'file:line' },
          signature: { type: 'string', description: 'the Lean type/signature, abbreviated' },
          role: { type: 'string', description: 'how it is used for the rigidification build' },
        },
        required: ['name', 'location', 'signature', 'role'],
      },
    },
    gaps: { type: 'array', items: { type: 'string' }, description: 'Missing pieces that would have to be built, each with an estimated shape/difficulty' },
    recipe: { type: 'string', description: 'Concrete construction recipe / term for the asked-for object, using the found decls' },
  },
  required: ['summary', 'decls', 'gaps', 'recipe'],
}

const P_SECTION =
  "You are mapping in-tree Lean API. Working dir: repo root. All paths under " + ROOT + ".\n\n" +
  "GOAL: CONSTRUCT the x0-section of the projection pi = pullback.snd C.hom piT : (C x_k T) -> T, from a k-rational point of C. Given k:Type u [Field k], C:Over (Spec (.of k)), [HasRationalPoint C] (class in FGAPicRepresentability.lean:139, field nonempty_section : Nonempty {sigma : Spec (.of k) -> C.left // sigma comp C.hom = 1}), and piT : T -> Spec (.of k). I want sigma_T : T -> Limits.pullback C.hom piT with sigma_T comp Limits.pullback.snd C.hom piT = 1. Natural construction: pullback.lift (piT comp x0) (id T) with the commuting proof, where x0 is the rational point.\n\n" +
  "Read FGAPicRepresentability.lean (HasRationalPoint :139 and any use of the section), StructureSheafPushforward.lean which takes sigma as a HYPOTHESIS hsigma : sigma comp pi = 1 in retraction_appTop_of_section :353, appTop_restrict_eq_of_section :363, eq_one_of_section_of_restrict_eq_one(_of_gate) :375/:388 — report the EXACT type of pi and sigma there so my constructed sigma_T matches. grep the tree for existing constructions (pullback.lift, Section, rationalPointSection, uses of nonempty_section).\n\n" +
  "DELIVER (schema): exact term for sigma_T with the commuting-square obligation; the EXACT type signature StructureSheafPushforward expects for sigma and pi; whether any helper already builds this. Exact file:line for every claim. Do NOT write files."

const P_AUT =
  "You are mapping in-tree Lean API. Working dir: repo root. All paths under " + ROOT + ".\n\n" +
  "GOAL: The landed lm:aut is RING-LEVEL (StructureSheafPushforward.lean: eq_one_of_section_of_restrict_eq_one_of_gate :388 — a global function u on C x T restricting to 1 along a section is 1). To get the geometric lm:aut (an automorphism of a rigidified locally-trivial line bundle L that is the identity along the x0-section is the identity) I need the bridge: End(L) iso Gamma(C x T, O) for L an invertible (IsLocallyTrivial) Modules object, as rings, i.e. every module endomorphism of invertible L is multiplication by a global function; restricting the automorphism along a section corresponds to restricting that global function.\n\n" +
  "Investigate whether this bridge or its pieces exist. Search (grep + read) for: End/Aut of Scheme.Modules objects; Hom(unit,unit) = Gamma(X,O); ring structure on End of the unit module; SheafOfModules.unit; Modules.exists_tensorObj_inverse (RelPicFunctor / TensorObjInverse); tensorObj_left_unitor; pullbackUnitIso; IsLocallyTrivial; any lemma identifying automorphisms of an invertible sheaf with global units or Hom(O,O) with global sections; how Scheme.Modules morphisms expose an .appTop / global-sections action.\n\n" +
  "DELIVER (schema): whether End(invertible L) iso Gamma(O) exists or must be built; if built, the SHORTEST path (e.g. Hom(L,L) iso Hom(O, L tensor Linv) iso Hom(O,O) iso Gamma(O) via exists_tensorObj_inverse + unitor + Hom(unit,unit)=Gamma), with the exact existing decls to chain; how a module automorphism section-restriction becomes sigma.appTop of the global function. Exact file:line. Do NOT write files."

const P_TRIV =
  "You are mapping in-tree Lean API. Working dir: repo root. All paths under " + ROOT + ".\n\n" +
  "GOAL: Map trivialization + twist API on OnProduct line bundles. A rigidification of L : LineBundle.OnProduct C.hom piT along sigma_T : T -> C x T is an iso (Modules.pullback sigma_T).obj L.carrier iso SheafOfModules.unit T.ringCatSheaf (sigma_T^* L iso O_T). The lm:fff twist: L' := L tensor piT^*((sigma_T^* L)inv) has a CANONICAL rigidification, since sigma_T^*(piT^* N) iso N (section of projection) so sigma_T^* L' iso sigma_T^* L tensor (sigma_T^* L)inv iso O_T.\n\n" +
  "Read LineBundlePullback.lean (OnProduct :130, pullbackAlongProjection :221, IsLocallyTrivial.pullback :156, pullback_pullback_eq :278), RelPicFunctor.lean (tensorObjOnProduct :235, relNegOnProduct :625, exists_tensorObj_inverse usage, pInverseUnique, tensorObj_left_unitor, pullbackUnitIso, pullbackTensorIsoOfLocallyTrivial :619, isLocallyTrivial_unit), and TensorObjInverse.lean / TensorObjSubstrate.lean for tensor-inverse and unit machinery.\n\n" +
  "DELIVER (schema): exact decls (signatures + file:line) for: SheafOfModules.unit + its IsLocallyTrivial witness; tensorObj on Modules; exists_tensorObj_inverse statement; left/right unitor isos; pullbackUnitIso (pullback of unit iso unit); pullbackTensorIsoOfLocallyTrivial (pullback commutes with tensor); and the section base-change iso sigma_T^*(piT^* N) iso N for a section sigma_T of piT (does it exist, via pullbackComp + pullbackCongr on sigma_T comp piT = id ? give the exact route). Provide the concrete term-level iso chain for sigma_T^* L' iso O_T. Exact file:line. Do NOT write files."

const P_WIRE =
  "You are mapping in-tree Lean API. Working dir: repo root. All paths under " + ROOT + ".\n\n" +
  "GOAL: Verify EXACTLY how the landed ring-level lm:aut lemmas plug in. Read StructureSheafPushforward.lean focusing on 250-395: isIso_snd_appTop :260, bijective_appTop_of_hasStructureSheafPushforwardIso :315, eq_apply_of_isRetraction :333, eq_one_of_isRetraction_of_restrict_eq_one :344, retraction_appTop_of_section :353, appTop_restrict_eq_of_section :363, eq_one_of_section_of_restrict_eq_one :375, eq_one_of_section_of_restrict_eq_one_of_gate :388, and the gate HasStructureSheafPushforwardIso + its unconditional instance instHasStructureSheafPushforwardIso (near 300-317).\n\n" +
  "I want: given a global function u : Gamma(C x T, O) with sigma.appTop u = 1, the EXACT lemma giving u = 1 UNCONDITIONALLY (no gate hypothesis, since isIso_snd_appTop is unconditional). Confirm eq_one_of_section_of_restrict_eq_one_of_gate is discharged by instHasStructureSheafPushforwardIso, so an unconditional u = 1 is available for arbitrary T. State the exact unconditional call (name, hypotheses, conclusion, file:line). Report precise types: what is sigma.appTop, what ring is Gamma(C x T, O) (the .appTop target), how pi.appTop composes.\n\n" +
  "DELIVER (schema): the single unconditional call chain from sigma.appTop u = 1 to u = 1 for arbitrary T (exact names + file:line), plus type-mismatch gotchas (op/appTop vs app top, which section sigma type). Do NOT write files."

const TASKS = [
  { label: 'section-from-rational-point', prompt: P_SECTION },
  { label: 'automorphism-unit-bridge', prompt: P_AUT },
  { label: 'trivialization-twist-api', prompt: P_TRIV },
  { label: 'ringlevel-lmaut-wiring', prompt: P_WIRE },
]

const results = await parallel(TASKS.map(t => () =>
  agent(t.prompt, { label: t.label, phase: 'Map', schema: FINDING_SCHEMA, model: 'sonnet', effort: 'medium' })
    .then(r => ({ label: t.label, ...r }))
))

return results.filter(Boolean)

